namespace sv_eea2591e124045f9aba2b5c893031750.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-1001"] = new Shipment
        {
            TrackingNumber = "PKG-1001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 21, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 15, 8, 0, 0, TimeSpan.FromHours(-5)), Description = "Package picked up", Location = "New York, NY" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 16, 14, 30, 0, TimeSpan.FromHours(-5)), Description = "Arrived at sorting facility", Location = "Philadelphia, PA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 17, 22, 15, 0, TimeSpan.FromHours(-5)), Description = "Departed facility", Location = "Columbus, OH" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 18, 6, 45, 0, TimeSpan.FromHours(-5)), Description = "In transit", Location = "Chicago, IL" },
            ]
        },
        ["PKG-2002"] = new Shipment
        {
            TrackingNumber = "PKG-2002",
            Status = "Delivered",
            Location = "Austin, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 17, 12, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 14, 9, 0, 0, TimeSpan.FromHours(-5)), Description = "Package picked up", Location = "Seattle, WA" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 15, 18, 0, 0, TimeSpan.FromHours(-5)), Description = "In transit", Location = "Denver, CO" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 16, 20, 0, 0, TimeSpan.FromHours(-5)), Description = "Out for delivery", Location = "Austin, TX" },
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 17, 10, 30, 0, TimeSpan.FromHours(-5)), Description = "Delivered", Location = "Austin, TX" },
            ]
        },
        ["PKG-3003"] = new Shipment
        {
            TrackingNumber = "PKG-3003",
            Status = "Label Created",
            Location = "Miami, FL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 25, 17, 0, 0, TimeSpan.FromHours(-4)),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTimeOffset(2026, 6, 18, 1, 0, 0, TimeSpan.FromHours(-4)), Description = "Shipping label created", Location = "Miami, FL" },
            ]
        },
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_eea2591e124045f9aba2b5c893031750.Client.Models
@using sv_eea2591e124045f9aba2b5c893031750.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h2>Shipment Tracker</h2>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <p><strong>Loading shipment @TrackingNumber…</strong></p>
        <p>Fetching tracking details, please wait.</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p><strong>@_errorMessage</strong></p>
        <button class="btn btn-outline-danger mt-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="card mb-3">
        <div class="card-header">
            <strong>@_shipment.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            @if (_shipment.EstimatedDelivery.HasValue)
            {
                <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.Value.ToString("f")</p>
            }
        </div>
    </div>

    @if (_shipment.StatusUpdates.Count > 0)
    {
        <h4>Tracking History</h4>
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Date &amp; Time</th>
                    <th>Description</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates.OrderByDescending(u => u.Timestamp))
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Description</td>
                        <td>@update.Location</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        // Cancel any in-flight request when the tracking number changes
        CancelPending();

        _cts = new CancellationTokenSource();

        await LoadShipmentAsync(_cts.Token);
    }

    private async Task LoadShipmentAsync(CancellationToken ct)
    {
        _loading = true;
        _errorMessage = null;
        _shipment = null;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation away or disposal — silently stop.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading the shipment. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync()
    {
        CancelPending();
        _cts = new CancellationTokenSource();
        await LoadShipmentAsync(_cts.Token);
    }

    private void CancelPending()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        CancelPending();
    }
}

